// --- 快速练习生成器 ---
function quickBasicGen() {
  let type = ri(0, 3);
  let a, b;
  switch(type) {
    case 0: a = ri(10, 99); b = ri(10, 99); return makeChoice(`${a} + ${b} = ?`, a + b, [a+b+1, a+b-1, a+b+10]);
    case 1: a = ri(50, 99); b = ri(10, 49); return makeChoice(`${a} - ${b} = ?`, a - b, [a-b+1, a-b-1, a-b+10]);
    case 2: a = ri(2, 9); b = ri(2, 9); return makeChoice(`${a} × ${b} = ?`, a * b, [a*b+1, a*b-1, a*b+a]);
    case 3: b = ri(2, 9); let q = ri(2, 9); a = b * q; return makeChoice(`${a} ÷ ${b} = ?`, q, [q+1, q-1, q+2]);
  }
}

