// ============================================================
// 巧数三角形（专项30题）—— 由外部归档卷子整合而来
// ============================================================
// 在 0 0 120 100 的 viewBox 内绘制三角形计数图（内层 svg 内容）
function triSVG(n, layers, diagonal) {
  const top = [60, 12], left = [16, 82], right = [104, 82];
  const baseW = right[0] - left[0];
  const segs = [];
  for (let i = 0; i <= n; i++) segs.push(left[0] + baseW * i / n);
  let s = `<polygon points="${top[0]},${top[1]} ${right[0]},${right[1]} ${left[0]},${left[1]}" fill="none" stroke="#334155" stroke-width="3"/>`;
  if (layers > 1) {
    const ys = [];
    for (let L = 1; L <= layers; L++) ys.push(top[1] + (left[1] - top[1]) * L / layers);
    ys.forEach((y, L) => {
      const x1 = left[0] + (top[0] - left[0]) * (y - left[1]) / (top[1] - left[1]);
      const x2 = right[0] + (top[0] - right[0]) * (y - left[1]) / (top[1] - left[1]);
      s += `<line x1="${x1.toFixed(1)}" y1="${y.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y.toFixed(1)}" stroke="#64748b" stroke-width="2"/>`;
    });
    ys.forEach((y, L) => { s += `<text x="${(right[0] + 3).toFixed(1)}" y="${(y + 3).toFixed(1)}" font-size="9" fill="#94a3b8">${L + 1}层</text>`; });
  }
  for (let i = 1; i < n; i++) {
    s += `<line x1="${segs[i].toFixed(1)}" y1="${top[1]}" x2="${segs[i].toFixed(1)}" y2="${left[1]}" stroke="#64748b" stroke-width="2"/>`;
  }
  if (diagonal) {
    const dX1 = left[0] + baseW * 0.15, dY1 = left[1], dY2 = top[1] + (left[1] - top[1]) * 0.35;
    s += `<line x1="${dX1.toFixed(1)}" y1="${dY1}" x2="${right[0]}" y2="${dY2.toFixed(1)}" stroke="#dc2626" stroke-width="2.5" stroke-dasharray="5,3"/>`;
    s += `<text x="${(right[0] - 6).toFixed(1)}" y="${((dY2 + dY1) / 2).toFixed(1)}" font-size="9" fill="#dc2626">斜</text>`;
  }
  for (let i = 1; i <= n; i++) {
    const cx = (segs[i - 1] + segs[i]) / 2;
    s += `<text x="${cx.toFixed(1)}" y="97" text-anchor="middle" font-size="10" fill="#2563eb" font-weight="700">${i}</text>`;
  }
  return s;
}

