const TRI_Q = TRI_RAW.map(r => {
  const svg = triSVG(r.n, r.l, r.d);
  if (r.t === 'c') {
    const labels = ['A', 'B', 'C', 'D'];
    return {
      type: 'choice', question: r.q, svg: svg,
      options: r.o.map((v, i) => ({ label: labels[i], value: v })),
      answer: r.o[r.a], answerIdx: r.a
    };
  }
  return { type: 'fill', question: r.q, svg: svg, answer: String(r.ans), inputType: 'number' };
});

let _triIdx = 0;
function g_triangle_count() {
  const q = TRI_Q[_triIdx % TRI_Q.length];
  _triIdx++;
  return q;
}

function loadData() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || { wrong: [], stats: {}, history: [] };
  } catch(e) {
    return { wrong: [], stats: {}, history: [] };
  }
}

function saveData(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

// 错题库为数学/英语共用存储，getWrongBank 只返回「数学」错题（无 module 字段的历史数据视为数学）
function getAllWrongBank() { return loadData().wrong || []; }
function getWrongBank() { return getAllWrongBank().filter(w => !w.module || w.module === '数学'); }
function addToWrongBank(question, userAnswer, unitName, grade) {
  let data = loadData();
  // 避免重复
  let existing = data.wrong.find(w => w.question === question.question && w.answer === question.answer);
  if (existing) {
    existing.count = (existing.count || 1) + 1;
    existing.lastWrong = Date.now();
  } else {
    data.wrong.push({
      id: Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      question: question,
      userAnswer: userAnswer,
      unitName: unitName,
      grade: grade,
      time: Date.now(),
      count: 1
    });
  }
  saveData(data);
}

function removeFromWrongBank(id) {
  let data = loadData();
  data.wrong = data.wrong.filter(w => w.id !== id);
  saveData(data);
}

function clearWrongBank() {
  let data = loadData();
  data.wrong = [];
  saveData(data);
}

function recordHistory(grade, unitName, score, total, wrong) {
  let data = loadData();
  if (!data.history) data.history = [];
  data.history.unshift({
    grade: grade,
    unitName: unitName,
    score: score,
    total: total,
    accuracy: Math.round(score / total * 100),
    time: Date.now(),
    wrong: Array.isArray(wrong) ? wrong : [],
    synced: false
  });
  if (data.history.length > 50) data.history = data.history.slice(0, 50);

  if (!data.stats) data.stats = {};
  if (!data.stats[grade]) data.stats[grade] = { totalDone: 0, totalCorrect: 0 };
  data.stats[grade].totalDone += total;
  data.stats[grade].totalCorrect += score;

  saveData(data);
}

// ============================================================
// 页面导航
// ============================================================
function showPage(pageId) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-' + pageId).classList.add('active');
  window.scrollTo(0, 0);
}

function switchTab(tab) {
  document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
  document.querySelector(`.nav-tab[data-page="${tab}"]`).classList.add('active');

  if (tab === 'home') {
    showPage('home');
    document.getElementById('backBtn').style.display = 'none';
    renderHome();
  } else if (tab === 'wrong') {
    showPage('wrong');
    document.getElementById('backBtn').style.display = 'none';
    renderWrongBank();
  } else if (tab === 'stats') {
    showPage('stats');
    document.getElementById('backBtn').style.display = 'none';
    renderStats();
  } else if (tab === 'exam') {
    showPage('exam');
    document.getElementById('backBtn').style.display = 'none';
    renderExamCenter();
  } else if (tab === 'parent') {
    showPage('parent');
    document.getElementById('backBtn').style.display = 'none';
    renderParent();
  }
}

function goBack() {
  if (state.quizMode === 'exam') {
    if (confirm('确定要交卷并退出本次考试吗？')) {
      if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }
      switchTab('exam');
      state.quizMode = null;
      state.quizQuestions = [];
      state.quizIndex = 0;
      state.quizScore = 0;
      state.quizCorrect = 0;
      state.quizWrong = 0;
      state.quizWrongQuestions = [];
    }
    return;
  }
  if (state.quizMode === 'unit' || state.quizMode === 'quick' || state.quizMode === 'wrong' || state.quizMode === 'upload') {
    if (confirm('确定要退出本次练习吗？')) {
      goHome();
    }
  } else {
    goHome();
  }
}

function goHome() {
  state.quizQuestions = [];
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.selectedAnswer = null;
  state.answered = false;
  state.examPaper = null;
  state.quizMode = null;
  if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }
  document.getElementById('examPaperHeader').style.display = 'none';
  switchTab('home');
}

// ============================================================
// 拍图上传 & AI 识别
// ============================================================
let uploadedImageDataURL = null;
let recognizedQuestionsList = [];

// 处理图片上传
function handleImageUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  // 检查文件大小（限制10MB）
  if (file.size > 10 * 1024 * 1024) {
    showToast('图片太大了，请选择10MB以内的图片');
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e) {
    uploadedImageDataURL = e.target.result;
    document.getElementById('previewImg').src = uploadedImageDataURL;
    document.getElementById('uploadPreview').style.display = 'block';
    document.getElementById('recognizeStatus').innerHTML = '<div style="color:var(--primary);font-size:14px">正在识别题目...</div>';
    document.getElementById('recognizedQuestions').innerHTML = '';

    // 调用AI识别
    recognizeImage(file);
  };
  reader.readAsDataURL(file);
}

// 调用AI识别图片中的数学题
async function recognizeImage(file) {
  try {
    // 将图片转为base64
    const base64 = await fileToBase64(file);

    // 调用云端AI识别
    const result = await callAIRecognize(base64, file.type);

    if (result && result.questions && result.questions.length > 0) {
      recognizedQuestionsList = result.questions;
      displayRecognizedQuestions(result.questions);
    } else {
      // 识别失败，提示手动输入
      document.getElementById('recognizeStatus').innerHTML = `
        <div style="color:var(--accent);font-size:13px">
          ⚠️ 未能自动识别题目<br>
          <span style="font-size:12px">请使用下方"手动输入"功能</span>
        </div>`;
    }
  } catch (err) {
    console.error('识别失败:', err);
    document.getElementById('recognizeStatus').innerHTML = `
      <div style="color:var(--accent);font-size:13px">
        ⚠️ 识别服务暂时不可用<br>
        <span style="font-size:12px">请使用下方"手动输入"功能</span>
      </div>`;
  }
}

// 文件转base64
function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// 调用AI接口识别题目
async function callAIRecognize(base64Data, mimeType) {
  // 使用 Tesseract.js 进行纯前端 OCR 识别
  try {
    // 动态加载 Tesseract.js
    if (typeof Tesseract === 'undefined') {
      await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');
    }

    document.getElementById('recognizeStatus').innerHTML = '<div style="color:var(--primary);font-size:13px">正在加载识别引擎...</div>';

    const worker = await Tesseract.createWorker('chi_sim+eng', 1, {
      logger: m => {
        if (m.status === 'recognizing text') {
          let pct = Math.round(m.progress * 100);
          document.getElementById('recognizeStatus').innerHTML = `<div style="color:var(--primary);font-size:13px">识别中... ${pct}%</div>`;
        }
      }
    });

    const { data: { text } } = await worker.recognize(uploadedImageDataURL);
    await worker.terminate();

    // 解析识别到的文字
    let questions = parseRecognizedText(text);
    return { questions: questions, rawText: text };
  } catch(e) {
    console.error('OCR error:', e);
    return null;
  }
}

// 动态加载脚本
function loadScript(src) {
  return new Promise((resolve, reject) => {
    let script = document.createElement('script');
    script.src = src;
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

// 解析 OCR 识别的文字为数学题
function parseRecognizedText(text) {
  let lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 1);
  let questions = [];

  lines.forEach(line => {
    // 清理常见OCR错误
    line = line.replace(/[oO](?=\s*[+\-×÷])|(?<=[+\-×÷]\s*)[oO]/g, '0');
    line = line.replace(/l(?=\d)/g, '1');
    line = line.replace(/\|/g, '1');
    line = line.replace(/[×xX]/g, '×');
    line = line.replace(/[÷]/g, '÷');

    let q = parseMathExpression(line);
    if (q) questions.push(q);
  });

  return questions;
}

// 显示识别到的题目
function displayRecognizedQuestions(questions) {
  let status = document.getElementById('recognizeStatus');
  status.innerHTML = `<div style="color:var(--success);font-size:14px;font-weight:600">识别到 ${questions.length} 道题目</div>`;

  let html = '<div style="text-align:left;margin-top:12px">';
  questions.forEach((q, i) => {
    html += `<div style="background:var(--bg);border-radius:8px;padding:10px 12px;margin-bottom:8px">
      <div style="font-size:12px;color:var(--text-lighter);margin-bottom:4px">第${i+1}题</div>
      <div style="font-size:15px;font-weight:600">${q.question}</div>
      ${q.answer ? `<div style="font-size:13px;color:var(--success);margin-top:4px">答案：${q.answer}</div>` : ''}
    </div>`;
  });
  html += '</div>';
  html += `<button class="btn btn-primary" style="margin-top:12px" onclick="startUploadQuiz()">开始答题</button>`;
  document.getElementById('recognizedQuestions').innerHTML = html;
}

// 手动输入解析
function parseManualInput() {
  let text = document.getElementById('manualInput').value.trim();
  if (!text) {
    showToast('请输入题目内容');
    return;
  }

  let lines = text.split('\n').map(l => l.trim()).filter(l => l);
  let questions = [];

  lines.forEach(line => {
    let q = parseMathExpression(line);
    if (q) questions.push(q);
  });

  if (questions.length === 0) {
    showToast('未能解析题目，请检查格式');
    return;
  }

  recognizedQuestionsList = questions;
  displayRecognizedQuestions(questions);
  showToast(`成功解析 ${questions.length} 道题目`);
}

// 解析数学表达式
function parseMathExpression(text) {
  // 去除题号
  text = text.replace(/^\d+[\.、\)]\s*/, '');

  // 检测运算表达式：如 "3 + 5 = ?" "8 × 7 = ?"
  let match = text.match(/^(\d+(?:\.\d+)?)\s*([+\-×÷*/])\s*(\d+(?:\.\d+)?)\s*=\s*\??$/);
  if (match) {
    let a = parseFloat(match[1]);
    let op = match[2];
    let b = parseFloat(match[3]);
    let answer;
    switch(op) {
      case '+': answer = a + b; break;
      case '-': answer = a - b; break;
      case '×': case '*': answer = a * b; break;
      case '÷': case '/': answer = b !== 0 ? (a / b) : 0; break;
      default: return null;
    }
    return makeChoice(`${a} ${op} ${b} = ?`, answer, [answer+1, answer-1, answer+ri(2,5)]);
  }

  // 检测 "X + Y = Z" 形式（已知结果，求运算）
  match = text.match(/^(\d+(?:\.\d+)?)\s*([+\-×÷*/])\s*(\d+(?:\.\d+)?)\s*=\s*(\d+(?:\.\d+)?)\s*[（(]?\s*([对错✓✗])?\s*[)）]?$/);
  if (match) {
    let a = parseFloat(match[1]), op = match[2], b = parseFloat(match[3]), result = parseFloat(match[4]);
    let actual;
    switch(op) {
      case '+': actual = a + b; break;
      case '-': actual = a - b; break;
      case '×': case '*': actual = a * b; break;
      case '÷': case '/': actual = b !== 0 ? a / b : 0; break;
    }
    let isCorrect = Math.abs(actual - result) < 0.001;
    return makeChoice(`${a} ${op} ${b} = ${result} 对吗？`, isCorrect ? '对' : '错', [isCorrect ? '错' : '对', '无法确定', '近似相等']);
  }

  // 检测应用题（包含文字描述）
  if (text.length > 5 && /[个元岁天人米分秒千克克本只条块瓶箱步层]/.test(text)) {
    // 尝试从文本中提取数字和关键词来生成选择题
    let nums = text.match(/\d+(?:\.\d+)?/g);
    if (nums && nums.length >= 2) {
      let a = parseFloat(nums[0]), b = parseFloat(nums[1]);
      // 尝试不同运算
      let ops = [
        { op: '+', result: a + b, label: `${a} + ${b}` },
        { op: '-', result: a - b, label: `${a} - ${b}` },
        { op: '×', result: a * b, label: `${a} × ${b}` },
      ];
      // 如果有"共""一共""总共"等词，用加法
      if (/共|一共|总共|合计/.test(text)) {
        let answer = a + b;
        return makeChoice(text.replace(/=\s*\??$/, '').replace(/\?+$/, '？'), answer, [answer+1, answer-1, answer+a]);
      }
      // 如果有"还剩""剩下""多"等词，用减法
      if (/还剩|剩下|多|少|差/.test(text)) {
        let answer = a - b;
        if (answer < 0) answer = b - a;
        return makeChoice(text.replace(/=\s*\??$/, '').replace(/\?+$/, '？'), answer, [answer+1, answer-1, answer+a]);
      }
      // 如果有"每""倍"等词，用乘法
      if (/每|倍|一共.*个/.test(text)) {
        let answer = a * b;
        return makeChoice(text.replace(/=\s*\??$/, '').replace(/\?+$/, '？'), answer, [answer+1, answer-1, answer+a]);
      }
      // 默认用加法
      let answer = a + b;
      return makeChoice(text.replace(/=\s*\??$/, '').replace(/\?+$/, '？'), answer, [answer+1, answer-1, answer+a]);
    }
  }

  // 检测比较大小
  match = text.match(/^(\d+(?:\.\d+)?)\s*[（(]\s*(\d+(?:\.\d+)?)\s*[)）]\s*$/);
  if (match) {
    let a = parseFloat(match[1]), b = parseFloat(match[2]);
    return makeChoice(`比较大小：${a} ○ ${b}`, a > b ? '>' : a < b ? '<' : '=', ['>', '<', '='].filter(x => x !== (a > b ? '>' : a < b ? '<' : '=')).slice(0, 3));
  }

  return null;
}

// 开始上传题目答题
function startUploadQuiz() {
  if (recognizedQuestionsList.length === 0) {
    showToast('没有可练习的题目');
    return;
  }
  state.quizMode = 'upload';
  state.quizTitle = '拍图练习';
  state.quizQuestions = recognizedQuestionsList.slice();
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
}

