function renderUnits() {
  let gradeNames = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级'};
  let semName = state.currentSemester == 1 ? '上册' : '下册';
  document.getElementById('unitsTitle').textContent = `${gradeNames[state.currentGrade]}${semName} · 单元列表`;

  let units = KNOWLEDGE_BASE[state.currentGrade][state.currentSemester];
  let listEl = document.getElementById('unitList');
  let data = loadData();

  listEl.innerHTML = '';
  units.forEach((unit, idx) => {
    let item = document.createElement('div');
    item.className = 'unit-item' + (unit.name.includes('专项') ? ' special-unit' : '');

    // 查看是否有练习记录
    let records = (data.history || []).filter(h => h.grade === state.currentGrade && h.unitName === unit.name);
    let bestScore = records.length > 0 ? Math.max(...records.map(r => r.accuracy)) : 0;

    let metaText = records.length > 0
      ? `<span class="unit-progress">最高正确率 ${bestScore}%</span>`
      : `<span style="font-size:12px;color:var(--text-lighter)">${getTypeName(unit.type)}</span>`;

    item.innerHTML = `
      <div class="unit-number">${idx + 1}</div>
      <div class="unit-info">
        <div class="unit-name">${unit.name}</div>
        <div class="unit-meta">${metaText}</div>
      </div>
      <div class="unit-arrow">›</div>
    `;
    item.onclick = () => startUnitQuiz(idx);
    listEl.appendChild(item);
  });
}

function getTypeName(type) {
  const names = { basic: '基础运算', application: '应用题', shape: '图形认知', mixed: '综合练习' };
  return names[type] || type;
}

