// ============================================================
// 数据备份与同步（导出 / 导入）
// ============================================================
function downloadBlob(content, filename, mime) {
  let blob = new Blob([content], { type: mime + ';charset=utf-8' });
  let url = URL.createObjectURL(blob);
  let a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}

function stamp() {
  let d = new Date();
  let p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}`;
}

function exportUserData() {
  let data = loadData();
  let payload = {
    app: '吕泳冀学习站',
    version: 1,
    exportedAt: new Date().toISOString(),
    data: data,
  };
  downloadBlob(JSON.stringify(payload, null, 2), `数学练习数据_${stamp()}.json`, 'application/json');
  showToast('已导出，可发送到电脑再导入');
}

function importUserData(event) {
  let file = event.target.files && event.target.files[0];
  if (!file) return;
  let reader = new FileReader();
  reader.onload = e => {
    try {
      let obj = JSON.parse(e.target.result);
      let incoming = obj && obj.data ? obj.data : obj;
      if (!incoming || typeof incoming !== 'object') throw new Error('格式不对');

      let cur = loadData();
      // 错题合并去重
      let merged = (cur.wrong || []).slice();
      let keys = new Set(merged.map(w => (w.question && w.question.question) + '|' + (w.question && w.question.answer)));
      (incoming.wrong || []).forEach(w => {
        let k = (w.question && w.question.question) + '|' + (w.question && w.question.answer);
        if (!keys.has(k)) { keys.add(k); merged.push(w); }
      });
      // 历史合并按时间倒序取前50条
      let history = (cur.history || []).concat(incoming.history || [])
        .sort((a, b) => (b.time || 0) - (a.time || 0)).slice(0, 50);
      // 统计相加
      let stats = Object.assign({}, cur.stats || {});
      Object.keys(incoming.stats || {}).forEach(g => {
        if (!stats[g]) stats[g] = { totalDone: 0, totalCorrect: 0 };
        stats[g].totalDone += incoming.stats[g].totalDone || 0;
        stats[g].totalCorrect += incoming.stats[g].totalCorrect || 0;
      });

      saveData({ wrong: merged, history: history, stats: stats });
      showToast(`导入成功：错题 ${merged.length} 道`);
      renderStats();
    } catch (err) {
      showToast('导入失败：文件格式不正确');
    }
    event.target.value = '';
  };
  reader.readAsText(file, 'utf-8');
}

function exportWrongBookText() {
  let bank = getWrongBank();
  if (bank.length === 0) { showToast('错题库是空的'); return; }
  let lines = ['小学数学错题本', '导出时间：' + new Date().toLocaleString('zh-CN'), '共 ' + bank.length + ' 道', ''];
  bank.forEach((w, i) => {
    let q = w.question || {};
    lines.push(`${i + 1}. 【${w.unitName || '未知单元'}】${(q.question || '').replace(/\n/g, ' ')}`);
    if (q.options && q.options.length) {
      let labels = ['A', 'B', 'C', 'D'];
      lines.push('   选项：' + q.options.map((o, k) => labels[k] + '. ' + (typeof o === 'object' ? o.value : o)).join('　'));
    }
    lines.push(`   正确答案：${q.answer}　我的答案：${w.userAnswer}　错误次数：${w.count || 1}`);
    lines.push('');
  });
  downloadBlob(lines.join('\n'), `错题本_${stamp()}.txt`, 'text/plain');
  showToast('错题本已导出');
}

